const LANGS={"de":{"name":"Deutsch","flag":"🇩🇪"},"en":{"name":"English","flag":"🇬🇧"},"ar":{"name":"العربية","flag":"🇸🇦"},"zh":{"name":"中文","flag":"🇨🇳"},"fr":{"name":"Français","flag":"🇫🇷"},"it":{"name":"Italiano","flag":"🇮🇹"},"ja":{"name":"日本語","flag":"🇯🇵"},"ko":{"name":"한국어","flag":"🇰🇷"},"pt":{"name":"Português","flag":"🇵🇹 🇧🇷"},"ru":{"name":"Русский","flag":"🇷🇺"},"es":{"name":"Español","flag":"🇪🇸"},"am":{"name":"አማርኛ","flag":"🇪🇹"},"el":{"name":"Ελληνικά","flag":"🇬🇷"},"he":{"name":"עברית","flag":"🇮🇱"},"tr":{"name":"Türkçe","flag":"🇹🇷"}};
const FLAG_CODES={"de":["de"],"en":["gb"],"ar":["sa"],"zh":["cn"],"fr":["fr"],"it":["it"],"ja":["jp"],"ko":["kr"],"pt":["pt","br"],"ru":["ru"],"es":["es"],"am":["et"],"el":["gr"],"he":["il"],"tr":["tr"]};
function flagImage(cc,alt=''){return `<img src="flags/${cc}.png" srcset="flags/${cc}.png 2x" alt="${String(alt||'').replace(/"/g,'&quot;')}">`}
function languageFlagMarkup(lang){const x=LANGS[lang]||LANGS.de,codes=FLAG_CODES[lang]||FLAG_CODES.de;if(codes.length===1)return flagImage(codes[0],x.name);return `<span class="aj-flag-pair" aria-label="${x.name}">${codes.map((c,i)=>flagImage(c,i===0?'Portugal':'Brasilien')).join('')}</span>`;}
